INSERT INTO t_grammar_lesson (id, day_no, title, stage, mode, content, question_count, pass_score) VALUES
(1, 1, '名词考点', '七天掌握全部词法、时态和语态', '学习', '[{"text": "可数名词变复数，记住四个套路：", "example": null}, {"text": "① 一般直接加 -s（book→books）", "example": null}, {"text": "② 以 s, x, sh, ch 结尾加 -es（bus→buses, watch→watches）", "example": null}, {"text": "③ 辅音字母+y 结尾，把 y 变成 i 再加 -es（city→cities, baby→babies）", "example": null}, {"text": "④ 以 f 或 fe 结尾，把 f 变成 v 再加 -es（leaf→leaves, knife→knives）", "example": "two cities, three babies, many leaves"}, {"text": "以 o 结尾的词分两类：", "example": null}, {"text": "有生命的（土豆番茄英雄黑人）加 -es：tomato→tomatoes, hero→heroes", "example": null}, {"text": "没生命的（照片收音机钢琴）加 -s：photo→photos, piano→pianos, radio→radios", "example": "potatoes and tomatoes vs. photos and pianos"}, {"text": "不规则复数必须死记：", "example": null}, {"text": "man→men, woman→women, foot→feet, tooth→teeth, child→children, mouse→mice", "example": null}, {"text": "单复数同形：sheep→sheep, deer→deer, fish→fish（ fishes 指不同种类的鱼）", "example": "two men, three children, five sheep"}, {"text": "不可数名词只有单数形式，不能加 a/an，谓语动词用单数：", "example": null}, {"text": "口诀：\\"新闻建议信息家具，行李装备知识进度\\"", "example": null}, {"text": "news, advice, information, furniture, luggage, equipment, knowledge, progress", "example": "The news is exciting. (不是are) Much furniture was damaged. (不是were)"}, {"text": "名词所有格——谁的？", "example": null}, {"text": "有生命的用 ''s：Tom''s book（Tom的书）", "example": null}, {"text": "两人共有只在最后一个加：Tom and Jerry''s room（共用的房间）", "example": null}, {"text": "两人分别有各自都加：Tom''s and Jerry''s rooms（各自的房间）", "example": null}, {"text": "无生命的用 of：the top of the mountain", "example": "my parents'' car (父母的车) the window of the room"}, {"text": "名词当形容词用（修饰另一个名词），通常用单数：", "example": null}, {"text": "shoe store（鞋店，不是shoes store）, ticket office（售票处）", "example": null}, {"text": "但 man/woman 修饰复数名词时，自己也要变复数：", "example": null}, {"text": "men teachers（男教师们）, women doctors（女医生们）", "example": "a shoe store vs. three men teachers"}]', 3, 60),
(2, 2, '冠词考点', '七天掌握全部词法、时态和语态', '学习', '[{"text": "a 还是 an？看发音不看字母！", "example": null}, {"text": "辅音音素开头用 a：a university（/j/开头）, a one-eyed man（/w/开头）", "example": null}, {"text": "元音音素开头用 an：an hour（h不发音）, an honest man（h不发音）, an MBA（/e/开头）", "example": "a European country (eu发音/j/) an FBI agent (F发音/e/)"}, {"text": "什么时候用 the（定冠词）？", "example": null}, {"text": "① 特指——双方都知道的：Pass me the salt.", "example": null}, {"text": "② 上文提过的再提：I bought a book. The book is interesting.", "example": null}, {"text": "③ 世界上独一无二的：the sun, the moon, the earth, the sky", "example": null}, {"text": "④ 序数词和最高级前：the first, the best, the most beautiful", "example": null}, {"text": "⑤ 演奏乐器：play the piano, play the violin", "example": "The sun rises in the east. He is the tallest in our class."}, {"text": "什么时候不用冠词（零冠词）？", "example": null}, {"text": "① 球类/棋类前：play basketball, play chess（但乐器要加 the）", "example": null}, {"text": "② 三餐前：have breakfast/lunch/dinner", "example": null}, {"text": "③ 节日/月份/星期前：on Monday, in May, at Christmas", "example": null}, {"text": "④ 学科/语言前：study English, learn math", "example": null}, {"text": "⑤ 名词前有物主代词/指示代词：my book, this pen（不再加 the）", "example": "play football vs. play the piano have breakfast vs. have a meal"}, {"text": "固定搭配别搞混：", "example": null}, {"text": "in the morning/afternoon/evening（加the）", "example": null}, {"text": "但 at noon/night/midnight（不加the）", "example": null}, {"text": "in hospital = 住院（看病）/ in the hospital = 在医院（办事）", "example": null}, {"text": "go to school = 上学 / go to the school = 去学校（办事）", "example": null}, {"text": "go to bed = 上床睡觉 / go to the bed = 走向那张床", "example": "He is in hospital. (住院) I went to the school to pick up my son. (去学校接孩子)"}, {"text": "a/an + 序数词 = \\"再来一次\\"", "example": null}, {"text": "the + 序数词 = \\"第几次\\"", "example": null}, {"text": "try a second time = 再试一次", "example": null}, {"text": "the second time = 第二次", "example": "Can I try a third time? (能再试第三次吗？) This is the third time I''ve been here. (这是我第三次来)"}]', 3, 60),
(3, 3, '形容词和副词', '七天掌握全部词法、时态和语态', '学习', '[{"text": "-ing 还是 -ed？一句话搞定：", "example": null}, {"text": "-ing 形容词修饰\\"东西\\"（让人感到...的）：exciting news, boring movie", "example": null}, {"text": "-ed 形容词修饰\\"人\\"（人感到...的）：excited people, bored students", "example": null}, {"text": "记忆：东西发出 -ing，人感受 -ed", "example": "The movie is exciting. I am excited. The book is boring. I am bored."}, {"text": "比较级和最高级怎么变？", "example": null}, {"text": "短词（1个音节）：加 -er / -est（tall→taller→tallest）", "example": null}, {"text": "以 e 结尾：加 -r / -st（large→larger→largest）", "example": null}, {"text": "辅音+y 结尾：y变i加 -er/-est（happy→happier→happiest）", "example": null}, {"text": "重读闭音节：双写末辅音（big→bigger→biggest, hot→hotter→hottest）", "example": null}, {"text": "长词（2+音节）：前加 more / most（beautiful→more beautiful→most beautiful）", "example": "taller, hotter, happier more important, most carefully"}, {"text": "七个不规则变化必须背：", "example": null}, {"text": "good/well → better → best", "example": null}, {"text": "bad→worse→worst（坏/差）", "example": null}, {"text": "many/much → more → most（多）", "example": null}, {"text": "little → less → least（少）", "example": null}, {"text": "far → farther/further → farthest/furthest（远）", "example": null}, {"text": "old → older/elder → oldest/eldest（老）", "example": "better and best worse and worst"}, {"text": "比较级的常见句型：", "example": null}, {"text": "① as + 原级 + as：和...一样（as fast as）", "example": null}, {"text": "② not as/so + 原级 + as：不如...（not so fast as）", "example": null}, {"text": "③ 比较级 + than：比...更（faster than）", "example": null}, {"text": "④ the + 比较级, the + 比较级：越...越...（The more, the better.）", "example": null}, {"text": "⑤ 比较级 + and + 比较级：越来越...（better and better）", "example": "He is as tall as his brother. The harder you work, the luckier you get. Days are getting longer and longer."}, {"text": "副词放在哪里？", "example": null}, {"text": "频率副词（always/usually/often/sometimes/never）：放在be动词后、实义动词前", "example": null}, {"text": "程度副词（very/quite/too/so）：放在被修饰词前面", "example": null}, {"text": "enough 比较特殊：放在形容词/副词后面（good enough, fast enough）", "example": "He is always late. (be后) He always works hard. (实义动词前) He is old enough to drive. (形容词后)"}, {"text": "三个高频搭配：", "example": null}, {"text": "① too...to... = 太...以至于不能（too tired to walk）", "example": null}, {"text": "② so...that... = 如此...以至于（so tired that he fell asleep）", "example": null}, {"text": "③ enough to do = 足够...可以（old enough to vote）", "example": "He is too young to go to school. It was so cold that the river froze. He is strong enough to lift the box."}]', 3, 60),
(4, 4, '两种过去时态', '七天掌握全部词法、时态和语态', '学习', '[{"text": "一般过去时 = 过去某个时间做了的事（已经做完了）", "example": null}, {"text": "结构：主语 + 动词过去式", "example": null}, {"text": "时间标志：yesterday, last week, in 2010, two days ago, just now", "example": null}, {"text": "动词过去式规则：加 -ed（work→worked）；e结尾加-d（live→lived）；辅音+y变i加-ed（study→ studied）；重读闭音节双写（stop→stopped）", "example": "I went to school yesterday. She studied English last year. They stopped talking when I came in."}, {"text": "过去进行时 = 过去某个具体时间正在做的事（还没做完）", "example": null}, {"text": "结构：was/were + doing", "example": null}, {"text": "时间标志：at 8:00 yesterday, at that time, when/while 引导的时间状语", "example": null}, {"text": "注意：I was reading at 9 pm. = 晚上9点我正在读书（不一定读完）", "example": "I was watching TV at 8 yesterday. What were you doing when I called you?"}, {"text": "一般过去时 vs 过去进行时——一句话区分：", "example": null}, {"text": "一般过去时强调\\"做完了\\"（I read a book. 我读了本书，读完了）", "example": null}, {"text": "过去进行时强调\\"正在做\\"（I was reading a book. 我当时正在读书，没说读完）", "example": "I cooked dinner. (做完饭了) I was cooking dinner when you called. (你打电话时我正在做饭)"}, {"text": "when vs while——搭配不同时态：", "example": null}, {"text": "when + 短暂动作（一般过去时）：When I came in, he was reading.", "example": null}, {"text": "while + 持续动作（过去进行时）：While he was reading, the phone rang.", "example": null}, {"text": "口诀：when接\\"短\\"，while接\\"长\\"", "example": "When the phone rang, I was sleeping. While I was sleeping, the phone rang."}, {"text": "不规则动词过去式高频词（必须背）：", "example": null}, {"text": "go→went, see→saw, take→took, give→gave, come→came", "example": null}, {"text": "buy→bought, bring→brought, think→thought, teach→taught, catch→caught", "example": null}, {"text": "write→wrote, drive→drove, ride→rode, rise→rose", "example": null}, {"text": "begin→began, drink→drank, sing→sang, swim→swam, run→ran", "example": "I went to Beijing last year. She taught us English. They ran to the station."}]', 3, 60),
(5, 5, '现在时和将来时', '七天掌握全部词法、时态和语态', '学习', '[{"text": "一般现在时 = 习惯、经常做的事，或客观事实", "example": null}, {"text": "结构：主语 + 动词原形（三单加 -s/-es）", "example": null}, {"text": "时间标志：always, usually, often, sometimes, every day, on Sundays", "example": null}, {"text": "三单变化：works, goes, watches, studies, passes shopping on weekends.", "example": "The earth moves around the sun. (客观真理) He usually gets up at 6. (习惯) She often goes"}, {"text": "现在进行时 = 此时此刻正在做的事", "example": null}, {"text": "结构：am/is/are + doing", "example": null}, {"text": "时间标志：now, at the moment, Look!, Listen!", "example": null}, {"text": "注意：状态动词不用进行时——know, believe, like, love, want, need, belong, own", "example": null}, {"text": "（不能说 I am knowing him. 要说 I know him.）", "example": "Look! The bus is coming. Listen! Someone is singing. I want some water. (不是am wanting)"}, {"text": "一般将来时 = 以后要做的事，两种结构：", "example": null}, {"text": "① will + 动词原形：临时决定、客观预测（I''ll help you. The rain will stop soon.）", "example": null}, {"text": "② be going to + 动词原形：已有计划、有迹象的预测（I''m going to visit Paris next month. Look at the clouds! It''s going to rain.）", "example": "I will call you later. (临时决定) I am going to study abroad next year. (已有计划)"}, {"text": "will vs be going to——怎么选？", "example": null}, {"text": "will：临场决定（你饿了？我给你做饭→I''ll cook for you.）", "example": null}, {"text": "be going to：早有打算（我打算明年考研→I''m going to take the exam next year.）", "example": null}, {"text": "be going to 也可以表示\\"看迹象要发生\\"（乌云密布→It''s going to rain.） (计划)", "example": "— It''s cold here. — I''ll close the window. (临时) I''ve bought a ticket. I''m going to see the movie."}, {"text": "\\"主将从现\\"——重要规则！", "example": null}, {"text": "在 if / when / as soon as / before / after 引导的时间或条件状语从句中，", "example": null}, {"text": "主句用将来时，从句用一般现在时表将来：", "example": null}, {"text": "If it rains tomorrow, I will stay home.", "example": null}, {"text": "（不是 If it will rain...）", "example": null}, {"text": "When he comes, I will tell him.", "example": "If it doesn''t rain tomorrow, we will go hiking. As soon as I arrive, I will call you."}]', 3, 60),
(6, 6, '三种完成时态', '七天掌握全部词法、时态和语态', '学习', '[{"text": "现在完成时 = 过去做的事，对现在有影响；或从过去一直持续到现在的动作", "example": null}, {"text": "结构：have/has + 过去分词", "example": null}, {"text": "时间标志：already, yet, just, ever, never, since + 时间点, for + 时间段, so far, recently", "example": null}, {"text": "核心理解：强调\\"和现在的联系\\" (从2010年住到现在) Have you ever been to Japan? (你曾经去过日本吗？)", "example": "I have finished my homework. (作业已写完，现在可以玩了) She has lived here since 2010."}, {"text": "过去完成时 = \\"过去的过去\\"", "example": null}, {"text": "在过去的某个时间点之前，已经做完的事", "example": null}, {"text": "结构：had + 过去分词", "example": null}, {"text": "时间标志：by the end of last..., before/when 引导的过去时间", "example": null}, {"text": "核心理解：有两个过去时间，先发生的用过去完成时 (火车先走，我后到) He had finished dinner before I called him.", "example": "By the end of last year, they had built 10 bridges. When I arrived, the train had left."}, {"text": "将来完成时 = 到将来某个时间点之前，会已经做完的事", "example": null}, {"text": "结构：will have + 过去分词", "example": null}, {"text": "时间标志：by the end of next..., by the time + 将来时间", "example": null}, {"text": "核心理解：站在未来回头看", "example": "By next month, I will have graduated. By the time you come back, I will have finished the work."}, {"text": "三个易混点：", "example": null}, {"text": "① have been to = 去过（已回来）：I have been to Shanghai twice.", "example": null}, {"text": "② have gone to = 去了（还没回来）：He has gone to Shanghai. (他还在上海)", "example": null}, {"text": "③ since vs for：since + 时间点（since 2010, since Monday）, for + 时间段（for 3 years, for 2 hours） 2019", "example": "I have been to Beijing. (去过，回来了) He has gone to Beijing. (去了，还没回) for 5 years vs. since"}, {"text": "过去分词怎么变？", "example": null}, {"text": "规则动词：和过去式一样加 -ed（work→worked→worked）", "example": null}, {"text": "不规则动词需要单独记（必须背！）：", "example": null}, {"text": "go→went→gone, see→saw→seen, write→wrote→written", "example": null}, {"text": "take→took→taken, give→gave→given, break→broke→broken", "example": null}, {"text": "eat→ate→eaten, fall→fell→fallen, do→did→done", "example": "I have gone... (应该说 I have been... 或 He has gone...) The window has been broken."}]', 3, 60),
(7, 7, '语态（被动语态）', '七天掌握全部词法、时态和语态', '学习', '[{"text": "被动语态 = 主语是动作的\\"承受者\\"，而不是\\"发出者\\"", "example": null}, {"text": "结构：be + 过去分词", "example": null}, {"text": "什么时候用被动？不知道谁做的、不重要谁做的、强调动作承受者", "example": null}, {"text": "The book was written by him. (书是被他写的——强调书) (桥被建于1990)", "example": "English is spoken in many countries. (英语被说——不强调谁说的) The bridge was built in 1990."}, {"text": "各时态的被动形式（背这张表就够了）：", "example": null}, {"text": "一般现在时：am/is/are + done", "example": null}, {"text": "一般过去时：was/were + done", "example": null}, {"text": "一般将来时：will be + done", "example": null}, {"text": "现在完成时：have/has been + done", "example": null}, {"text": "过去完成时：had been + done", "example": null}, {"text": "现在进行时：am/is/are being + done", "example": null}, {"text": "含情态动词：can/must be + done tomorrow. The room has been cleaned. The room must be cleaned.", "example": "The room is cleaned every day. The room was cleaned yesterday. The room will be cleaned"}, {"text": "主动变被动三步走：", "example": null}, {"text": "① 宾语→主语（提前）", "example": null}, {"text": "② 谓语→be + 过去分词（时态不变）", "example": null}, {"text": "③ 主语→by + 宾格（后置）", "example": null}, {"text": "He wrote the book → The book was written by him. will be built by them.", "example": "Tom broke the window → The window was broken by Tom. They will build a school → A school"}, {"text": "这些动词不用被动！", "example": null}, {"text": "① 不及物动词：happen, occur, take place, break out（发生、爆发——没有宾语，怎么被动？）", "example": null}, {"text": "② 系动词：look, sound, smell, taste, feel（感觉类——后面接形容词，不是被动）", "example": null}, {"text": "③ 表示\\"拥有\\"的动词：have, own, belong to, fit, cost（状态——不是动作） belongs to me. (不是is belonged to me)", "example": "The war broke out. (不是was broken out) The food tastes good. (不是is tasted good) This book"}, {"text": "两个特殊被动：", "example": null}, {"text": "① 带双宾语：give sb. sth. → sb. is given sth. 或 sth. is given to sb.", "example": null}, {"text": "② 使役/感官动词还原 to：", "example": null}, {"text": "主动 make sb. do → 被动 sb. is made to do（被动要还原 to！）", "example": null}, {"text": "主动 see sb. do → 被动 sb. is seen to do (主动省略to，被动还原)", "example": "He was given a book. / A book was given to him. He was made to work overtime."}]', 3, 60),
(8, 8, '主谓一致', '七天掌握四大重点', '学习', '[{"text": "三条原则要分清：", "example": null}, {"text": "① 语法一致：主语单数→谓语单数；主语复数→谓语复数（最基本）", "example": null}, {"text": "② 就近一致：谓语跟最近的主语走", "example": null}, {"text": "③ 就远一致：谓语跟较远的主语走（中间有 with 等连接时）", "example": "The boy likes music. / The boys like music. (语法一致)"}, {"text": "就近一致——谓语跟\\"最近的\\"走：", "example": null}, {"text": "使用场景：there be, not only...but also..., neither...nor..., either...or..., not...but...", "example": null}, {"text": "Neither he nor I am a teacher. (跟I走，用am)", "example": null}, {"text": "Either you or he is right. (跟he走，用is)", "example": null}, {"text": "There is a book and two pens. (跟a book走，用is) (跟I走)", "example": "Not only the students but also the teacher likes it. (跟teacher走) Neither you nor I am wrong."}, {"text": "就远一致——谓语跟\\"较远的\\"走（不受中间成分影响）：", "example": null}, {"text": "搭配：A with/besides/except/as well as B → 谓语跟 A", "example": null}, {"text": "The teacher with his students is visiting the museum. (跟teacher，用is)", "example": null}, {"text": "Tom, as well as his brothers, likes football. (跟Tom，用likes)", "example": "The manager, together with his staff, was present. (跟manager，用was)"}, {"text": "意义一致——看\\"意思\\"而不是\\"形式\\"：", "example": null}, {"text": "看起来复数实际单数：news, physics, mathematics, politics → 谓语用单数", "example": null}, {"text": "看起来单数实际复数：police, people, cattle → 谓语用复数", "example": null}, {"text": "看整体还是看成员：family/team/class/audience", "example": null}, {"text": "当整体看→单数（My family is large.）", "example": null}, {"text": "当成员看→复数（My family are watching TV.） The committee are arguing. (成员)", "example": "The news is exciting. (单数) The police are coming. (复数) The committee is meeting now. (整体)"}, {"text": "the number of vs a number of——最容易考！", "example": null}, {"text": "the number of + 复数名词 → 谓语用单数（中心词是 number）", "example": null}, {"text": "The number of students is 2000. (学生数量是2000)", "example": null}, {"text": "a number of + 复数名词 → 谓语用复数（意思是\\"许多\\"）", "example": null}, {"text": "A number of students are absent. (许多学生缺席)", "example": "The number of books is increasing. (单数) A number of books are missing. (复数)"}, {"text": "each/every + 单数名词 → 谓语用单数", "example": null}, {"text": "both A and B → 谓语用复数", "example": null}, {"text": "every...and every... → 谓语用单数（每个...和每个...都）", "example": null}, {"text": "Each boy and each girl has a chance. woman is welcome. (单数)", "example": "Every student has a book. (单数) Both Tom and Jerry are here. (复数) Every man and every"}]', 3, 60),
(9, 9, '非谓语动词', '七天掌握四大重点', '学习', '[{"text": "什么是非谓语？一个句子里只能有一个\\"真谓语\\"（被时态变化的那个），其他动词必须\\"变形\\"——变成 to do / doing / done，这就是非谓语。", "example": null}, {"text": "三种形式：", "example": null}, {"text": "① to do（不定式）：表目的、将来", "example": null}, {"text": "② doing（动名词/现在分词）：表习惯、进行、主动", "example": null}, {"text": "③ done（过去分词）：表完成、被动 needs repair. (broken 是非谓语)", "example": "I want to go home. (to go 是非谓语) He enjoys reading. (reading 是非谓语) The broken window"}, {"text": "哪些动词后面只能接 doing（背口诀）：", "example": null}, {"text": "\\"避免错过享建议，考虑练习不介意，", "example": null}, {"text": "逃避否认想象逃，推迟冒险不放弃\\"", "example": null}, {"text": "avoid, miss, enjoy, suggest, consider, practice, mind,", "example": null}, {"text": "escape, deny, imagine, postpone, risk, give up", "example": null}, {"text": "另外：be worth, feel like, can''t help 也接 doing", "example": "I enjoy reading novels. He suggested going by train. The book is worth reading."}, {"text": "哪些动词后面只能接 to do：", "example": null}, {"text": "want, hope, wish, expect, decide, plan, agree, promise,", "example": null}, {"text": "refuse, manage, offer, fail, pretend, happen, seem, appear", "example": null}, {"text": "口诀：\\"希望决定计划答应，拒绝设法提供假装\\"", "example": "I decided to leave early. He promised to help me. She seems to know everything."}, {"text": "doing 和 to do 意思不同——高频考点！", "example": null}, {"text": "stop doing = 停止正在做的事 / stop to do = 停下来去做另一件事", "example": null}, {"text": "remember doing = 记得做过（已做）/ remember to do = 记得要做（还没做）", "example": null}, {"text": "forget doing = 忘了做过（已做）/ forget to do = 忘了要做（还没做）", "example": null}, {"text": "try doing = 试着做看看效果 / try to do = 努力设法做 (记得锁了) Remember to lock the door. (记得要锁)", "example": "I stopped smoking. (不抽了) I stopped to smoke. (停下来去抽一根) I remember locking the door."}, {"text": "分词作状语——看主语是主动还是被动：", "example": null}, {"text": "现在分词 doing = 主动、同时发生", "example": null}, {"text": "过去分词 done = 被动、先于主句发生", "example": null}, {"text": "判断方法：看分词和主句主语的关系", "example": null}, {"text": "主语\\"发出\\"动作→用 doing", "example": null}, {"text": "主语\\"承受\\"动作→用 done looks beautiful. (城市被看→Seen)", "example": "Seeing from the hill, I found the city beautiful. (我主动看→Seeing) Seen from the hill, the city"}, {"text": "使役动词——to 省不省？", "example": null}, {"text": "make/have/let sb. do sth.（主动省略 to）", "example": null}, {"text": "但变被动后要还原 to：sb. is made to do sth.", "example": null}, {"text": "get sb. to do sth.（get 不省略 to） get him to help you. (get不省to)", "example": "The boss made him work overtime. (主动省to) He was made to work overtime. (被动还原to) I''ll"}]', 3, 60),
(10, 10, '复习非谓语', '七天掌握四大重点', '复习', '[{"text": "动名词 vs 不定式作主语——细微区别：", "example": null}, {"text": "doing 作主语 = 习惯性、已知的事（Swimming is good for health. 游泳对健康有益）", "example": null}, {"text": "to do 作主语 = 具体的、一次性的、将来的事（To finish this book is not easy. 读完这本书不容易）", "example": "Reading books is fun. (习惯) To read this book today is my plan. (具体)"}, {"text": "need/want/require + doing = + to be done（主动表被动）", "example": null}, {"text": "The room needs cleaning. = The room needs to be cleaned.（房间需要被打扫）", "example": null}, {"text": "这个用法很常见，doing 形式但表示被动含义 want to be watered.", "example": "My car needs washing. = My car needs to be washed. The flowers want watering. = The flowers"}, {"text": "分词作定语——位置和含义：", "example": null}, {"text": "现在分词作定语 = 主动、进行：a sleeping baby（正在睡觉的婴儿 = a baby who is sleeping）", "example": null}, {"text": "过去分词作定语 = 被动、完成：a broken window（被打破的窗户 = a window that is broken）", "example": null}, {"text": "单个分词放在名词前，分词短语放在名词后", "example": "a crying baby (正在哭的婴儿) a retired teacher (退休教师) the book written by him (他写的书)"}, {"text": "独立主格——分词有自己的\\"小主语\\"：", "example": null}, {"text": "当分词的逻辑主语和主句主语不同时，分词前面加上自己的逻辑主语", "example": null}, {"text": "Weather permitting, we''ll go hiking. (Weather 是 permitting 的主语，和主句主语 we 不同)", "example": null}, {"text": "The meeting over, everyone went home. (会议结束了，大家各自回家) to play.", "example": "The sun having set, we returned home. (太阳落山后我们回家) His homework finished, he went out"}]', 3, 60),
(11, 11, '情态动词', '七天掌握四大重点', '学习', '[{"text": "情态动词表推测——专升本必考！", "example": null}, {"text": "must be → 一定是（肯定推测）：He must be a teacher. (他一定是老师)", "example": null}, {"text": "can''t be → 一定不是（否定推测）：He can''t be a teacher. (他一定不是老师)", "example": null}, {"text": "may/might be → 可能是（不确定）：He may be a teacher. (他可能是老师)", "example": null}, {"text": "注意：肯定推测用 must，否定推测用 can''t（不用 mustn''t！） (一定不在家) He might be at home. (可能在家)", "example": "The light is on. He must be at home. (一定在家) The door is locked. He can''t be at home."}, {"text": "对过去的推测——must/can''t/should + have done：", "example": null}, {"text": "must have done = 过去一定做了（He must have studied hard. 他一定努力学了）", "example": null}, {"text": "can''t have done = 过去一定没做（He can''t have done it. 他一定没做）", "example": null}, {"text": "should have done = 本应该做但没做（含责备：You should have told me. 你本该告诉我的）", "example": null}, {"text": "needn''t have done = 本不必做但做了（You needn''t have worried. 你本不必担心的） You needn''t have bought so much. (你本不必买这么多)", "example": "The ground is wet. It must have rained last night. You should have come earlier. (你本该早点来)"}, {"text": "must vs have to——区别在哪？", "example": null}, {"text": "must = 主观意愿（我自己必须做）：I must study hard. (我决心要努力)", "example": null}, {"text": "have to = 客观需要（不得不做）：I have to wear a uniform. (规定要求)", "example": null}, {"text": "另外：must 没有过去式/将来式，需要用 had to / will have to 替代", "example": "I must lose weight. (主观决心) I have to work overtime. (客观需要)"}, {"text": "mustn''t ≠ don''t have to——很多人搞混！", "example": null}, {"text": "mustn''t = 禁止（绝对不能做）：You mustn''t smoke here. (禁止吸烟)", "example": null}, {"text": "don''t have to = 不必（不需要做但也可以做）：You don''t have to come. (不必来，但想来也行)", "example": "You mustn''t touch it. (禁止碰) You don''t have to help me. (不必帮忙)"}, {"text": "其他情态动词用法：", "example": null}, {"text": "can/could = 能力/请求（Could you help me?）", "example": null}, {"text": "shall = 征求意见（Shall we go?）/ 命令（You shall do it.）", "example": null}, {"text": "should/ought to = 应该（You should study hard.）", "example": null}, {"text": "used to = 过去常常（He used to smoke, but now he doesn''t.）", "example": null}, {"text": "had better (not) do = 最好（不）做", "example": "I could swim at age 5. Shall we dance? You''d better not stay up late."}]', 3, 60),
(12, 12, '虚拟语气', '七天掌握四大重点', '学习', '[{"text": "虚拟语气 = 说\\"假设\\"的话，不是真实发生的事", "example": null}, {"text": "if 条件句的虚拟分三种情况：", "example": null}, {"text": "① 与现在相反：If + 过去式(be→were), 主句 would/could/should/might + do", "example": null}, {"text": "If I were you, I would go. (如果我是你，我就会去——但我不是你)", "example": null}, {"text": "② 与过去相反：If + had done, 主句 would/could/should/might + have done", "example": null}, {"text": "If I had known, I would have helped. (如果我早知道，我就帮了——但我不知道)", "example": null}, {"text": "③ 与将来相反：If + were to do / should do, 主句 would/could/should/might + do", "example": null}, {"text": "If it were to rain tomorrow, I would stay home. (万一明天下雨) should have money, I would buy a car. (将来)", "example": "If I had money, I would buy a car. (现在) If I had had money, I would have bought a car. (过去) If I"}, {"text": "省略 if 的倒装——考试常考！", "example": null}, {"text": "如果 if 从句中有 had / were / should，可以省略 if，把它们提到句首", "example": null}, {"text": "If I had known → Had I known", "example": null}, {"text": "If I were you → Were I you", "example": null}, {"text": "If it should rain → Should it rain (= If I were you...)", "example": "Had I known the truth, I would have told you. (= If I had known...) Were I you, I would accept it."}, {"text": "wish 后面的虚拟——和 if 条件句一样的时态：", "example": null}, {"text": "wish + 过去式 = 与现在相反（I wish I were taller. 真希望我高一点）", "example": null}, {"text": "wish + had done = 与过去相反（I wish I had studied harder. 真希望当初更努力）", "example": null}, {"text": "wish + would/could do = 与将来相反（I wish it would stop raining. 真希望雨能停） (将来)", "example": "I wish I were a bird. (现在) I wish I had bought that house. (过去) I wish you would stop talking."}, {"text": "\\"建议命令要求\\"类动词后的虚拟——用 (should) + 动词原形：", "example": null}, {"text": "suggest, insist, demand, require, request, order, propose, advise, recommend", "example": null}, {"text": "这些词后面的宾语从句，谓语用 (should) + 动词原形，should 可以省略", "example": null}, {"text": "The teacher suggested that every student (should) read this book. today. It is required that everyone (should) wear a uniform.", "example": "He insisted that I (should) go with him. The boss ordered that the work (should) be finished"}, {"text": "其他虚拟句型：", "example": null}, {"text": "① would rather + 过去式（现在/将来）/ had done（过去）：I would rather you didn''t smoke.", "example": null}, {"text": "② It is (high) time that + 过去式 / should do：It''s time we went home.", "example": null}, {"text": "③ as if/as though + 过去式（现在）/ had done（过去）：He talks as if he knew everything.", "example": null}, {"text": "④ but for / without = 如果没有：But for your help, I would have failed. Without water, we couldn''t live.", "example": "I would rather you came tomorrow. It''s high time that we left. He looks as if he had seen a ghost."}]', 3, 60),
(13, 13, '复习虚拟语气', '七天掌握四大重点', '复习', '[{"text": "错综时间虚拟——从句和主句时间不同：", "example": null}, {"text": "If I had studied harder (过去), I would have a better job now (现在).", "example": null}, {"text": "从句说过去的事，主句说现在的结果，各自用对应时态", "example": "If I had taken the medicine yesterday, I would be better now. (昨天吃药→现在会好)"}, {"text": "but for / without = \\"如果没有\\"——相当于虚拟条件句：", "example": null}, {"text": "But for your help, I would have failed. = If it had not been for your help, I would have failed.", "example": null}, {"text": "Without air, no one could live. = If there were no air, no one could live.", "example": "But for the rain, we would have gone out. Without your support, I couldn''t have done it."}, {"text": "if only 感叹句 = \\"要是...就好了\\"：", "example": null}, {"text": "与现在相反：If only I were younger! (要是我年轻点就好了)", "example": null}, {"text": "与过去相反：If only I had known! (要是我早知道就好了)", "example": null}, {"text": "形式和 wish 一样", "example": "If only I had more money! If only I hadn''t said that!"}, {"text": "insist 的两种用法——虚拟 vs 不虚拟：", "example": null}, {"text": "insist 表示\\"坚持要求某人做某事\\"→ 虚拟 (should) do", "example": null}, {"text": "He insisted that I (should) stay. (他非要我留下)", "example": null}, {"text": "insist 表示\\"坚称某事是真的\\"→ 不虚拟，用陈述语气", "example": null}, {"text": "He insisted that he was right. (他坚称自己是对的)", "example": "He insisted that I should go. (坚持要求→虚拟) He insisted that he was innocent. (坚称→陈述)"}]', 3, 60),
(14, 14, '阶段总复习', '七天掌握四大重点', '自测', '[{"text": "综合复习本阶段全部内容：主谓一致、非谓语动词、情态动词、虚拟语气，以及第一阶段的词法、时态 和语态。", "example": null}, {"text": "重点回顾：", "example": null}, {"text": "① 就近/就远一致的搭配", "example": null}, {"text": "② doing vs to do 的区别", "example": null}, {"text": "③ must have done / should have done / needn''t have done", "example": null}, {"text": "④ if 虚拟语气三种时态", "example": null}, {"text": "⑤ 省略 if 的倒装", "example": null}]', 3, 60),
(15, 15, '反义疑问句', '七天掌握五大句型', '学习', '[{"text": "反义疑问句 = 陈述句 + 小尾巴问句", "example": null}, {"text": "基本规则：前肯后否，前否后肯", "example": null}, {"text": "He is a teacher, isn''t he? (前肯后否)", "example": null}, {"text": "He isn''t a teacher, is he? (前否后肯)", "example": null}, {"text": "尾巴的动词和前面保持一致：前面有 be/助动词/情态动词，尾巴就用同一个", "example": "You like music, don''t you? She can''t swim, can she? They have left, haven''t they?"}, {"text": "注意\\"隐藏的否定词\\"——看到这些词，前面就算否定句：", "example": null}, {"text": "never(从不), hardly(几乎不), seldom(很少), rarely(罕见),", "example": null}, {"text": "few(几乎没有), little(几乎没有), nobody, nothing", "example": null}, {"text": "含有这些词的句子，尾巴用肯定形式 (little→前否→后肯) She hardly speaks, does she? (hardly→前否→后肯)", "example": "He never comes late, does he? (never→前否→后肯) There is little water, is there?"}, {"text": "there be 句型的反义疑问：", "example": null}, {"text": "There is a book, isn''t there?", "example": null}, {"text": "There aren''t any students, are there?", "example": null}, {"text": "（尾巴用 there，不用 it/they）", "example": "There is something wrong, isn''t there? There won''t be a meeting, will there?"}, {"text": "祈使句的反义疑问——记住三句话：", "example": null}, {"text": "肯定祈使句 → will you / won''t you（Open the door, will you?）", "example": null}, {"text": "否定祈使句 → will you（Don''t smoke, will you?）", "example": null}, {"text": "Let''s... → shall we（Let''s go, shall we?）", "example": null}, {"text": "Let us... → will you（Let us go, will you?） you?", "example": "Close the window, will you? Don''t be late, will you? Let''s have dinner, shall we? Let me try, will"}, {"text": "think/believe/suppose + 宾语从句——\\"否定转移\\"：", "example": null}, {"text": "I don''t think he is right, is he?（尾巴跟从句走，不是跟主句）", "example": null}, {"text": "因为否定已经\\"转移\\"到主句了，所以从句视为肯定，尾巴用否定", "example": "I don''t believe he will come, will he? I don''t suppose it matters, does it?"}, {"text": "everything/nothing 作主语——尾巴用 it：", "example": null}, {"text": "Everything is ready, isn''t it?", "example": null}, {"text": "Nothing happened, did it?", "example": null}, {"text": "everybody/nobody 作主语——尾巴用 they：", "example": null}, {"text": "Everyone knows it, don''t they?", "example": "Everything goes well, doesn''t it? Nobody called, did they?"}]', 3, 60),
(16, 16, '感叹句', '七天掌握五大句型', '学习', '[{"text": "感叹句有两种形式——What 和 How：", "example": null}, {"text": "What + (a/an) + 形容词 + 名词 + 主语 + 谓语!", "example": null}, {"text": "How + 形容词/副词 + 主语 + 谓语!", "example": null}, {"text": "核心区别：强调\\"名词\\"用 What，强调\\"形容词/副词\\"用 How", "example": "What a beautiful day it is! (强调day→What) How beautiful the day is! (强调beautiful→How)"}, {"text": "What 的三种情况：", "example": null}, {"text": "① 可数单数：What a beautiful girl she is!（要加 a/an）", "example": null}, {"text": "② 可数复数：What beautiful flowers they are!（不加 a/an）", "example": null}, {"text": "③ 不可数：What good weather it is!（不加 a/an）", "example": null}, {"text": "判断可不可数很重要！weather, news, advice, water 都不可数", "example": "What an interesting book! (单数) What interesting books! (复数) What terrible weather! (不可数)"}, {"text": "How 的两种情况：", "example": null}, {"text": "① How + 形容词：How beautiful the girl is!", "example": null}, {"text": "② How + 副词：How fast he runs!", "example": null}, {"text": "How 后面直接跟形容词/副词，不跟名词", "example": "How cold it is today! How well she sings! How time flies! (固定搭配)"}, {"text": "What 和 How 可以互相转换：", "example": null}, {"text": "What a beautiful day it is! = How beautiful a day it is!", "example": null}, {"text": "注意转换时 How 后面的顺序：How + adj. + a/an + n.", "example": null}, {"text": "（不是 How a beautiful day，是 How beautiful a day）", "example": "What a good idea! = How good an idea! What an interesting story! = How interesting a story!"}, {"text": "感叹句常省略主语和谓语：", "example": null}, {"text": "What a pity! = What a pity (it is)!", "example": null}, {"text": "How wonderful! = How wonderful (it is)!", "example": null}, {"text": "What a shame!", "example": "What a surprise! How amazing! What a mess!"}]', 3, 60),
(17, 17, '强调句', '七天掌握五大句型', '学习', '[{"text": "强调句的结构——\\"是...才...\\"：", "example": null}, {"text": "It is/was + 被强调部分 + that/who + 句子其余部分", "example": null}, {"text": "可以强调主语、宾语、状语", "example": null}, {"text": "原句：I met Tom in the park yesterday.", "example": null}, {"text": "强调主语：It was I that/who met Tom in the park yesterday.", "example": null}, {"text": "强调宾语：It was Tom that/who I met in the park yesterday.", "example": null}, {"text": "强调状语：It was in the park that I met Tom yesterday.", "example": null}, {"text": "强调时间：It was yesterday that I met Tom in the park. because he was ill that he didn''t come. (强调原因)", "example": "It was Tom who helped me. (强调Tom) It was in 2010 that he graduated. (强调时间) It was"}, {"text": "判断方法——去掉 It is/was...that 后句子仍然完整：", "example": null}, {"text": "It was Tom that helped me. → Tom helped me. (完整)", "example": null}, {"text": "如果不是强调句，去掉后句子就不完整 (宾语前置)", "example": "It was yesterday that he came. → Yesterday he came. It is a book that I want. → A book I want."}, {"text": "强调谓语动词——用 do/does/did：", "example": null}, {"text": "He does like music. (他确实喜欢音乐)", "example": null}, {"text": "She did come yesterday. (她昨天确实来了)", "example": null}, {"text": "Do be careful! (一定要小心！)", "example": null}, {"text": "注意：只能强调肯定句的谓语，不能强调否定句和疑问句", "example": "I do believe you. (我确实相信你) He did finish the work. (他确实完成了) Do sit down! (请坐！)"}, {"text": "强调句的疑问形式：", "example": null}, {"text": "一般疑问句：Is/Was it + 被强调部分 + that...?", "example": null}, {"text": "Was it Tom that helped you? (是Tom帮助了你吗？)", "example": null}, {"text": "特殊疑问句：疑问词 + is/was it + that...?", "example": null}, {"text": "Who was it that helped you? (是谁帮助了你？)", "example": null}, {"text": "Where was it that you met him? (你是在哪里遇到他的？)", "example": "When was it that you arrived? What is it that you want? Why was it that he was angry?"}]', 3, 60),
(18, 18, '并列句和祈使句', '七天掌握五大句型', '学习', '[{"text": "并列句 = 两个独立分句用并列连词连接", "example": null}, {"text": "四大并列连词：", "example": null}, {"text": "① 并列：and（和、然后）, not only...but also...（不仅...而且...）", "example": null}, {"text": "② 转折：but（但是）, however（然而）, while（而）", "example": null}, {"text": "③ 选择：or（或者）, either...or...（要么...要么...）", "example": null}, {"text": "④ 因果：so（所以）, for（因为） (因果) Not only did he speak, but he also sang. (并列)", "example": "He is rich but unhappy. (转折) Hurry up, or you''ll be late. (选择) It was late, so we went home."}, {"text": "重要考点——\\"祈使句 + and/or + 将来句\\"：", "example": null}, {"text": "Work hard, and you will succeed. (努力，你就会成功→条件)", "example": null}, {"text": "Hurry up, or you will be late. (快点，否则你会迟到→否则)", "example": null}, {"text": "这种结构中，祈使句相当于 if 条件句", "example": null}, {"text": "Work hard, and... = If you work hard, you will...", "example": null}, {"text": "Hurry up, or... = If you don''t hurry up, you will... (= If you move, I''ll shoot)", "example": "Study hard, and you''ll pass the exam. (= If you study hard, you''ll pass) Don''t move, or I''ll shoot."}, {"text": "祈使句 = 命令、请求、建议、警告", "example": null}, {"text": "结构：动词原形开头，主语 you 通常省略", "example": null}, {"text": "肯定：Open the door. / Please sit down.", "example": null}, {"text": "否定：Don''t / Never + 动词原形", "example": null}, {"text": "加强语气：Do + 动词原形（Do sit down! 请务必坐下）", "example": "Stand up! Please be quiet. Don''t touch it! Never give up! Do be careful!"}, {"text": "not only...but also... 的倒装——高级考点：", "example": null}, {"text": "Not only 放在句首时，后面的分句要部分倒装", "example": null}, {"text": "Not only did he study hard, but he also helped others.", "example": null}, {"text": "（did he study 是倒装，he also helped 不倒装）", "example": "Not only is he smart, but he is also kind. Not only does she sing well, but she also dances"}]', 3, 60),
(19, 19, '倒装句', '七天掌握五大句型', '学习', '[{"text": "倒装 = 把谓语（或一部分）放到主语前面", "example": null}, {"text": "两种倒装：", "example": null}, {"text": "① 完全倒装：谓语全部放在主语前（Here comes the bus.）", "example": null}, {"text": "② 部分倒装：只把助动词/be动词/情态动词放到主语前（Never have I seen such a thing.） understand. (部分倒装)", "example": "Here comes the bus. (完全倒装) Never have I seen such a thing. (部分倒装) Only then did I"}, {"text": "完全倒装的触发词——方位/地点副词放句首：", "example": null}, {"text": "here, there, up, down, in, out, away, now, then", "example": null}, {"text": "Here comes the bus! (公交车来了！)", "example": null}, {"text": "Up went the rocket! (火箭升空了！)", "example": null}, {"text": "Away went the boy! (男孩跑走了！)", "example": null}, {"text": "注意：主语必须是名词，如果是代词则不倒装（Here he comes. 不倒装）", "example": "There goes the bell! (铃响了) Here comes the teacher! (老师来了) 但：Here he comes. (代词不倒装)"}, {"text": "部分倒装的触发词——否定词放句首：", "example": null}, {"text": "never, hardly, seldom, rarely, little, not only,", "example": null}, {"text": "not until, no sooner, in no case, by no means", "example": null}, {"text": "这些词放句首→后面的句子部分倒装", "example": null}, {"text": "Never have I seen such a beautiful place.", "example": null}, {"text": "Hardly had I arrived when it started to rain.", "example": null}, {"text": "Not only does he study hard, but he also helps others. (我几乎不知道)", "example": "Never shall I forget it. (永不忘记) Seldom does he go out. (很少出门) Little did I know about it."}, {"text": "No sooner...than... / Hardly...when... = \\"一...就...\\"：", "example": null}, {"text": "No sooner had I arrived than the phone rang. (我刚到电话就响了)", "example": null}, {"text": "Hardly had I sat down when the bell rang. (我刚坐下铃就响了)", "example": null}, {"text": "注意：这两个结构都用过去完成时（had done）", "example": "No sooner had he left than it rained. Hardly had she finished when the timer went off."}, {"text": "Only + 状语放句首→部分倒装：", "example": null}, {"text": "Only then did I realize my mistake. (只有那时我才意识到错误)", "example": null}, {"text": "Only by working hard can you succeed. (只有努力才能成功)", "example": null}, {"text": "Only when he came back did I tell him. (只有他回来时我才告诉他)", "example": null}, {"text": "注意：Only + 主语不倒装！（Only he knows the truth. 不倒装） do it. (主语不倒装)", "example": "Only in this way can we solve the problem. Only after the meeting did he call me. Only Tom can"}, {"text": "So + 形容词/副词 放句首→部分倒装：", "example": null}, {"text": "So beautiful is the girl that everyone likes her. (女孩如此美丽以至于大家都喜欢她)", "example": null}, {"text": "So fast did he run that no one could catch him.", "example": "So tired was he that he fell asleep immediately. So loudly did he speak that everyone heard."}]', 3, 60),
(20, 20, '复习五大句型', '七天掌握五大句型', '复习', '[{"text": "五大句型回顾：", "example": null}, {"text": "① 反义疑问句：前肯后否/前否后肯，注意隐藏否定词", "example": null}, {"text": "② 感叹句：What强调名词，How强调形容词/副词", "example": null}, {"text": "③ 强调句：It is/was...that/who...，去掉后句子仍完整", "example": null}, {"text": "④ 并列句和祈使句：and/or/so/but 连接，\\"祈使句+and/or+将来句\\"", "example": null}, {"text": "⑤ 倒装句：否定词/Only/So放句首→部分倒装；方位副词放句首→完全倒装", "example": null}]', 3, 60),
(21, 21, '五大句型自测', '七天掌握五大句型', '自测', '[{"text": "综合自测，检查五大句型掌握情况。", "example": null}]', 3, 60),
(22, 22, '主语从句', '七天掌握全部从句', '学习', '[{"text": "主语从句 = 一个句子当主语用", "example": null}, {"text": "That he passed the exam is a miracle. (他通过考试是个奇迹)", "example": null}, {"text": "What he said is true. (他说的是真的)", "example": null}, {"text": "Whether we will go is still unknown. (我们是否去还不知道) on the weather.", "example": "That she is beautiful is obvious. What you need is more practice. Whether he will come depends"}, {"text": "it 作形式主语——避免\\"头重脚轻\\"：", "example": null}, {"text": "It is a pity that he failed. (很遗憾他失败了)", "example": null}, {"text": "It is well-known that the earth is round. (众所周知地球是圆的)", "example": null}, {"text": "It is necessary that we should study hard. (我们必须努力学习)", "example": null}, {"text": "常用搭配：It is + adj./n./pp. + that... surprise that he won the prize.", "example": "It is important that we learn English well. It is reported that a new virus has appeared. It is a"}, {"text": "that vs whether——怎么选？", "example": null}, {"text": "that：本身无意义，只起连接作用，在从句中不充当成分", "example": null}, {"text": "That he is right is clear. (他是对的，这很清楚)", "example": null}, {"text": "whether：表示\\"是否\\"，有实际意义", "example": null}, {"text": "Whether he is right is unclear. (他是否对还不清楚)", "example": null}, {"text": "注意：if 不能引导主语从句！只能用 whether", "example": "That she loves him is obvious. (that无意义) Whether she loves him is a secret. (whether=是否)"}, {"text": "what 引导的主语从句——what 在从句中充当成分（主语/宾语/表语）：", "example": null}, {"text": "What he said surprised everyone. (what = the thing that，作said的宾语)", "example": null}, {"text": "What we need is more time. (what作need的宾语)", "example": null}, {"text": "What is done cannot be undone. (what作is done的主语) (what作happened主语)", "example": "What I want is a cup of coffee. (what作want宾语) What happened next was a mystery."}]', 3, 60),
(23, 23, '宾语从句', '七天掌握全部从句', '学习', '[{"text": "宾语从句 = 一个句子当宾语用", "example": null}, {"text": "I think (that) he is right. (我认为他是对的)", "example": null}, {"text": "I don''t know what happened. (我不知道发生了什么)", "example": null}, {"text": "He asked if/whether I could help him. (他问我是否能帮他) meeting starts?", "example": "I believe (that) you can do it. She wonders where he has gone. Can you tell me when the"}, {"text": "宾语从句的引导词选择：", "example": null}, {"text": "① that：从句是陈述句，that 无意义可省略", "example": null}, {"text": "I think (that) he is honest.", "example": null}, {"text": "② whether/if：从句是一般疑问句（是否）", "example": null}, {"text": "I don''t know whether/if he will come.", "example": null}, {"text": "③ what/who/when/where/why/how：从句是特殊疑问句", "example": null}, {"text": "I don''t know where he lives. (特殊疑问)", "example": "I know that she loves music. (陈述) I wonder if he is at home. (是否) Tell me why you are late."}, {"text": "whether vs if——什么时候只能用 whether：", "example": null}, {"text": "① 介词后：It depends on whether it rains. (不能用if)", "example": null}, {"text": "② 与 or not 连用：I don''t know whether or not he will come.", "example": null}, {"text": "③ 在 discuss 后：We discussed whether we should go.", "example": null}, {"text": "④ 引导主语/表语/同位语从句时只能用 whether not连用)", "example": "It depends on whether he agrees. (介词后用whether) I don''t know whether to go or not. (与or"}, {"text": "宾语从句的语序——永远是陈述语序！", "example": null}, {"text": "正确：I don''t know where he lives. (不是where does he live)", "example": null}, {"text": "正确：Can you tell me when the meeting starts? (不是when does the meeting start)", "example": null}, {"text": "正确：He asked what I was doing. (不是what was I doing) why did she cry.", "example": "I don''t know where he went. I don''t know where did he go. Tell me why she cried. Tell me"}, {"text": "宾语从句的时态一致——主句过去时，从句也用过去时：", "example": null}, {"text": "He said he was tired. (主句过去→从句过去)", "example": null}, {"text": "She told me she had finished. (主句过去→从句过去完成)", "example": null}, {"text": "注意：从句说的是客观真理时，时态不变：", "example": null}, {"text": "The teacher told us that the earth is round. (客观真理仍用现在时) boils at 100°C. (真理用现在时)", "example": "He said he would come. (过去将来时) She said she had eaten. (过去完成时) The teacher said water"}]', 3, 60),
(24, 24, '表语从句', '七天掌握全部从句', '学习', '[{"text": "表语从句 = 一个句子当表语用（放在系动词后面）", "example": null}, {"text": "The question is whether he will come. (问题是他是否会来)", "example": null}, {"text": "That is what I want to say. (那就是我想说的)", "example": null}, {"text": "It looks as if it is going to rain. (看起来要下雨了)", "example": "The truth is that I don''t know. This is why he was angry. The problem is how we can solve it."}, {"text": "常用系动词：be, look, seem, appear, remain, stay", "example": null}, {"text": "The reason is that... (原因是...)", "example": null}, {"text": "The question is whether... (问题是是否...)", "example": null}, {"text": "It seems that... (似乎...)", "example": null}, {"text": "It looks as if... (看起来好像...) looks as if it will snow.", "example": "The reason is that he was ill. The question is whether we should go. It seems that he is right. It"}, {"text": "表语从句的引导词：", "example": null}, {"text": "that：引导陈述内容（The truth is that he lied.）", "example": null}, {"text": "whether：表示\\"是否\\"（The question is whether we can finish.）", "example": null}, {"text": "what/who/where/when/why/how：特殊疑问含义", "example": null}, {"text": "This is how he did it. (这就是他做的方式)", "example": null}, {"text": "That is why I was late. (那就是我迟到的原因)", "example": null}, {"text": "注意：表语从句中不能用 if，只能用 whether born. That is why she cried.", "example": "The problem is that we have no money. The question is whether he agrees. This is where I was"}, {"text": "The reason why... is that...——固定句型：", "example": null}, {"text": "The reason why he was late is that he missed the bus.", "example": null}, {"text": "注意：用 that 不用 because！（不能说 The reason is because...）", "example": "The reason why he failed is that he didn''t study. The reason why she cried is that she was sad."}]', 3, 60),
(25, 25, '同位语从句', '七天掌握全部从句', '学习', '[{"text": "同位语从句 = 解释一个抽象名词的具体内容", "example": null}, {"text": "常用的抽象名词：fact, idea, news, hope, belief, truth, doubt, question, suggestion, advice, order, demand, possibility", "example": null}, {"text": "The news that he won the prize excited everyone. (他获奖的消息让大家兴奋)", "example": null}, {"text": "The fact that the earth is round is known to all. (地球是圆的这个事实众所周知) fact that she lied shocked us all.", "example": "The news that he passed the exam is true. The idea that we should help each other is good. The"}, {"text": "同位语从句 vs 定语从句——容易混淆！", "example": null}, {"text": "同位语从句：that 是连接词，不充当成分，不省略，从句解释名词内容", "example": null}, {"text": "The news that he won is true. (that不充当成分，从句=news的内容)", "example": null}, {"text": "定语从句：that 是关系代词，充当成分（主/宾），可省略，从句修饰名词", "example": null}, {"text": "The news that he told me is true. (that作told的宾语，从句修饰news) (that作told宾语)", "example": "同位语：The fact that he is honest is true. (that不充当) 定语：The fact that he told me is true."}, {"text": "判断方法——去掉 that 后：", "example": null}, {"text": "从句完整 → 同位语从句（that 只起连接作用）", "example": null}, {"text": "从句不完整 → 定语从句（that 充当了成分）", "example": null}, {"text": "\\"The news that he won is true\\" → he won 完整 → 同位语", "example": null}, {"text": "\\"The news that he told me is true\\" → he told me 缺宾语 → 定语 (he had缺宾语→定语)", "example": "The idea that we should go is good. (we should go完整→同位语) The idea that he had is good."}, {"text": "同位语从句的引导词：", "example": null}, {"text": "that：最常用，解释名词内容（The fact that he lied...）", "example": null}, {"text": "whether：表示\\"是否\\"（The question whether we should go...）", "example": null}, {"text": "how/when/where/why：特殊疑问含义", "example": null}, {"text": "I have no idea when he will come. (我不知道他什么时候来)", "example": null}, {"text": "The question how we can solve it remains. (我们如何解决它的问题还在) offer is still under discussion. I have no idea where he has gone.", "example": "The news that he arrived safely made us happy. The question whether we should accept the"}]', 3, 60),
(26, 26, '定语从句', '七天掌握全部从句', '学习', '[{"text": "定语从句 = 一个句子当形容词用，修饰前面的名词（先行词）", "example": null}, {"text": "The man who lives next door is a doctor. (住在隔壁的那个人是医生)", "example": null}, {"text": "The book which I bought yesterday is interesting. (我昨天买的那本书很有趣)", "example": null}, {"text": "This is the place where I was born. (这是我出生的地方) lived is old.", "example": "The girl who is singing is my sister. The car that he bought is very expensive. The house where I"}, {"text": "关系代词怎么选——看先行词和在从句中的成分：", "example": null}, {"text": "① 修饰人：who（作主语/宾语）, whom（作宾语）, whose（作定语）", "example": null}, {"text": "The man who called you is my teacher. (who作主语)", "example": null}, {"text": "The man (who/whom) I met is a doctor. (who/whom作宾语，可省略)", "example": null}, {"text": "The man whose car was stolen is upset. (whose作定语)", "example": null}, {"text": "② 修饰物：which（作主语/宾语）, that（人/物均可）", "example": null}, {"text": "The book which is on the table is mine. (which作主语)", "example": null}, {"text": "The book (which) I read was great. (which作宾语，可省略) student whose father is a doctor is my friend.", "example": "The girl who teaches us English is young. The movie that I watched last night was great. The"}, {"text": "that vs which——什么时候只能用 that：", "example": null}, {"text": "① 先行词有最高级修饰：the best book that I have ever read", "example": null}, {"text": "② 先行词有序数词修饰：the first thing that I did", "example": null}, {"text": "③ 先行词是不定代词 all, everything, anything, nothing, little, few", "example": null}, {"text": "Everything that he said is true.", "example": null}, {"text": "④ 先行词既有人又有物：the man and the dog that are in the garden", "example": null}, {"text": "什么时候只能用 which（不用 that）：", "example": null}, {"text": "① 介词后：the book in which I am interested（不能用that）", "example": null}, {"text": "② 引导非限制性定语从句（逗号后）：He passed the exam, which made us happy. which he lives is old. He failed, which disappointed everyone.", "example": "This is the best movie that I have ever seen. Everything that he did was wrong. The house in"}, {"text": "关系副词——when, where, why：", "example": null}, {"text": "when = 介词 + which（修饰时间名词）", "example": null}, {"text": "I remember the day when I first met her. (= on which)", "example": null}, {"text": "where = 介词 + which（修饰地点名词）", "example": null}, {"text": "This is the school where I studied. (= in which)", "example": null}, {"text": "why = for which（修饰 reason）", "example": null}, {"text": "That is the reason why he was late. (= for which) failed is laziness.", "example": "I''ll never forget the day when I graduated. This is the city where I was born. The reason why he"}, {"text": "非限制性定语从句——用逗号隔开，补充说明：", "example": null}, {"text": "My father, who is 60 years old, still works hard. (我父亲60岁了，仍在努力工作)", "example": null}, {"text": "He passed the exam, which surprised everyone. (他通过了考试，这让大家惊讶)", "example": null}, {"text": "注意：非限制性定语从句不能用 that，只能用 who/which", "example": null}, {"text": "which 可以指代整个主句：He came late, which made the teacher angry. phone, which cost me 5000 yuan.", "example": "My mother, who is a teacher, loves reading. He failed again, which was expected. I bought a new"}]', 3, 60),
(27, 27, '状语从句', '七天掌握全部从句', '学习', '[{"text": "状语从句 = 一个句子当副词用，修饰主句", "example": null}, {"text": "按功能分九大类：时间、地点、原因、条件、目的、结果、让步、方式、比较", "example": null}, {"text": "时间状语从句——when, while, as, before, after, since, until, as soon as", "example": null}, {"text": "when = 当...时（可接短暂/持续动作）", "example": null}, {"text": "while = 当...时（只能接持续动作）", "example": null}, {"text": "as = 一边...一边 / 随着", "example": null}, {"text": "until = 直到...才（not...until）", "example": null}, {"text": "as soon as = 一...就...", "example": null}, {"text": "注意：\\"主将从现\\"：主句将来时，从句现在时表将来 back. As soon as I get home, I will call you. I won''t leave until you come.", "example": "When I arrived, he was reading. While I was sleeping, the phone rang. I waited until he came"}, {"text": "原因状语从句——because, since, as, for", "example": null}, {"text": "because = 因为（语气最强，回答why提问）", "example": null}, {"text": "since/as = 既然/因为（已知原因，语气弱）", "example": null}, {"text": "for = 因为（补充说明，不放在句首）", "example": null}, {"text": "注意：because 不能和 so 连用！（Because... so...）", "example": "I was late because I missed the bus. Since you are here, let''s start. As it was raining, we stayed"}, {"text": "条件状语从句——if, unless, as long as", "example": null}, {"text": "if = 如果", "example": null}, {"text": "unless = 如果不（= if not）", "example": null}, {"text": "as long as = 只要", "example": null}, {"text": "注意：\\"主将从现\\"——主句将来时，从句用现在时 long as you are happy, I am happy.", "example": "If it rains, I will stay home. You won''t pass unless you study hard. (= if you don''t study hard) As"}, {"text": "让步状语从句——although, though, even though, while", "example": null}, {"text": "although/though = 虽然", "example": null}, {"text": "even though = 即使", "example": null}, {"text": "while = 虽然/然而", "example": null}, {"text": "注意：although/though 不能和 but 连用！（Although... but...）", "example": "Although he is poor, he is happy. Even though it was raining, we went out. While I respect your"}, {"text": "目的/结果状语从句", "example": null}, {"text": "目的：so that（为了）, in order that（为了）", "example": null}, {"text": "He studies hard so that he can pass the exam.", "example": null}, {"text": "结果：so...that（如此...以至于）, such...that", "example": null}, {"text": "He is so tired that he fell asleep.", "example": null}, {"text": "It was such a good movie that I saw it twice.", "example": null}, {"text": "so vs such：so + 形容词/副词；such + (a/an) + 形容词 + 名词 hot day that we stayed indoors.", "example": "He ran fast so that he could catch the bus. She is so kind that everyone likes her. It was such a"}]', 3, 60),
(28, 28, '复习六大从句', '七天掌握全部从句', '自测', '[{"text": "六大从句总结：", "example": null}, {"text": "① 主语从句：句子当主语，常用 It is...that... 形式", "example": null}, {"text": "② 宾语从句：句子当宾语，注意陈述语序和时态一致", "example": null}, {"text": "③ 表语从句：句子当表语，放在系动词后", "example": null}, {"text": "④ 同位语从句：解释抽象名词内容，that不充当成分", "example": null}, {"text": "⑤ 定语从句：修饰先行词，关系词在从句中充当成分", "example": null}, {"text": "⑥ 状语从句：修饰主句，分时间/原因/条件/让步/目的/结果等", "example": null}, {"text": "关键区分：", "example": null}, {"text": "• that 在名词性从句中不充当成分（同位语/主语/宾语/表语从句）", "example": null}, {"text": "• that/which/who 在定语从句中充当成分（主语/宾语）", "example": null}, {"text": "• whether 可用于所有从句，if 只能用于宾语从句", "example": null}]', 3, 60);
INSERT INTO t_grammar_question (id, lesson_id, type, stem, option_a, option_b, option_c, option_d, answer, analysis, knowledge_point, status) VALUES
(1, 1, 'CHOICE', 'There are many ______ in the hall.', 'woman teachers', 'women teachers', 'woman teacher', 'women teacher', 'B', 'man/woman 作定语时，其单复数随中心词一起变化。中心词 teacher 为复数，故用 women teachers。', '名词考点', 1),
(2, 1, 'CHOICE', 'The ______ of the two dictionaries are quite different.', 'price', 'prices', 'price''s', 'prices''', 'B', '表示两者各自的价格，用复数形式 prices。', '名词考点', 1),
(3, 1, 'CHOICE', 'He gave me some useful ______ on how to learn English well.', 'advices', 'advice', 'advise', 'advices''', 'B', 'advice 是不可数名词，没有复数形式；advise 是动词，注意区分词性。', '名词考点', 1),
(4, 2, 'CHOICE', 'She is ______ honest girl and we all like her.', 'a', 'an', 'the', '/', 'B', 'honest 中 h 不发音，单词实际以元音音素开头，用不定冠词 an。', '冠词考点', 1),
(5, 2, 'CHOICE', 'He plays ______ piano very well, but he doesn''t like ______ music.', 'the, the', '/, the', 'the, /', 'a, /', 'C', '乐器名称前加定冠词 the；music 表示泛指，不加冠词。', '冠词考点', 1),
(6, 2, 'CHOICE', '______ Great Wall is one of the wonders in the world.', 'A', 'An', 'The', '/', 'C', '世界上独一无二的事物前用定冠词 the。', '冠词考点', 1),
(7, 3, 'CHOICE', 'The soup tastes ______; I''d like some more.', 'good', 'well', 'nicely', 'badly', 'A', 'taste 是感官系动词，后接形容词作表语，选 good。', '形容词和副词', 1),
(8, 3, 'CHOICE', 'Of all the students in our class, he studies ______.', 'hard', 'harder', 'hardest', 'more hard', 'C', '三者以上比较用最高级；修饰动词 study 用副词 hardest。', '形容词和副词', 1),
(9, 3, 'CHOICE', 'The ______ you work, the ______ progress you will make.', 'harder, greater', 'hard, great', 'hardest, greatest', 'more hard, more great', 'A', '“the + 比较级，the + 比较级”表示“越……越……”。', '形容词和副词', 1),
(10, 4, 'CHOICE', 'I ______ my homework when the phone rang.', 'did', 'was doing', 'have done', 'do', 'B', 'when 引导的从句用一般过去时，主句动作正在进行，用过去进行时。', '两种过去时态', 1),
(11, 4, 'CHOICE', 'When I got to the cinema, the film ______ for ten minutes.', 'had begun', 'had been on', 'has begun', 'began', 'B', 'begin 是短暂性动词，与 for 时间段连用需换成延续性的 be on；表“过去的过去”用过去完成时。', '两种过去时态', 1),
(12, 4, 'CHOICE', 'She ______ to see me last week, but she didn''t come.', 'was going', 'would go', 'had gone', 'goes', 'A', 'was/were going to do 表示过去打算做但实际未做的事。', '两种过去时态', 1),
(13, 5, 'CHOICE', 'Look! The children ______ football on the playground.', 'play', 'played', 'are playing', 'have played', 'C', 'Look! 提示动作正在发生，用现在进行时。', '现在时和将来时', 1),
(14, 5, 'CHOICE', 'If it ______ tomorrow, we will stay at home.', 'rains', 'will rain', 'rained', 'is raining', 'A', '主将从现：if 引导的条件状语从句用一般现在时表示将来。', '现在时和将来时', 1),
(15, 5, 'CHOICE', 'Hurry up! The train ______ in ten minutes.', 'leaves', 'left', 'has left', 'is left', 'A', '按时刻表安排的将来动作，用一般现在时表示。', '现在时和将来时', 1),
(16, 6, 'CHOICE', 'I ______ in this city since 2018.', 'live', 'lived', 'have lived', 'had lived', 'C', 'since + 时间点与现在完成时连用，表示动作从过去持续到现在。', '三种完成时态', 1),
(17, 6, 'CHOICE', 'By the end of last year, we ______ over 2000 English words.', 'learned', 'have learned', 'had learned', 'learn', 'C', 'by the end of + 过去时间，句子用过去完成时。', '三种完成时态', 1),
(18, 6, 'CHOICE', '— Have you finished your homework? — Yes, I ______ it an hour ago.', 'have finished', 'finished', 'had finished', 'finish', 'B', '句中有明确的过去时间状语 an hour ago，只能用一般过去时。', '三种完成时态', 1),
(19, 7, 'CHOICE', 'The bridge ______ last year and now it is in use.', 'builds', 'built', 'was built', 'has built', 'C', '桥与“建造”是被动关系，时间为 last year，用一般过去时的被动语态。', '语态（被动语态）', 1),
(20, 7, 'CHOICE', 'A new hospital ______ in our town next year.', 'is built', 'will be built', 'will build', 'is building', 'B', '医院是“被建造”，且时间为将来，用 will be built。', '语态（被动语态）', 1),
(21, 7, 'CHOICE', 'The problem ______ at the meeting now.', 'discusses', 'is discussing', 'is being discussed', 'has discussed', 'C', 'now 表示动作正在进行，且问题是被讨论，用现在进行时的被动语态。', '语态（被动语态）', 1),
(22, 8, 'CHOICE', 'Neither Tom nor his parents ______ at home now.', 'is', 'are', 'was', 'has', 'B', 'neither...nor 连接并列主语时遵循就近原则，靠近谓语的是 parents，用复数 are。', '主谓一致', 1),
(23, 8, 'CHOICE', 'The number of the students in our school ______ about 2000.', 'is', 'are', 'have', 'were', 'A', 'the number of 意为“……的数量”，谓语动词用单数。', '主谓一致', 1),
(24, 8, 'CHOICE', 'Reading English books ______ my hobby.', 'are', 'is', 'were', 'be', 'B', '动名词短语作主语时，谓语动词用单数。', '主谓一致', 1),
(25, 9, 'CHOICE', 'I often hear him ______ English songs in the morning.', 'sing', 'singing', 'to sing', 'sang', 'A', 'hear sb. do sth. 表示听见某人做某事（强调全过程），动词前不加 to。', '非谓语动词', 1),
(26, 9, 'CHOICE', '______ from the top of the hill, the city looks beautiful.', 'Seeing', 'Seen', 'To see', 'See', 'B', '城市是“被看”，与逻辑主语是被动关系，用过去分词作状语。', '非谓语动词', 1),
(27, 9, 'CHOICE', 'He is used to ______ up early every day.', 'get', 'getting', 'got', 'be got', 'B', 'be used to doing sth. 表示“习惯于做某事”，to 是介词，后接动名词。', '非谓语动词', 1),
(28, 10, 'CHOICE', 'The boy ______ by the window is my brother.', 'stand', 'standing', 'stood', 'to stand', 'B', '现在分词作后置定语，表示主动、正在进行的动作。', '复习非谓语', 1),
(29, 10, 'CHOICE', 'He hurried to the station, only ______ that the train had gone.', 'finding', 'found', 'to find', 'find', 'C', 'only to do 表示出乎意料的结果。', '复习非谓语', 1),
(30, 10, 'CHOICE', '______ his homework, he went out to play basketball.', 'Finished', 'Finishing', 'To finish', 'Having finished', 'D', '该动作发生在主句动作之前，用现在分词的完成式作时间状语。', '复习非谓语', 1),
(31, 11, 'CHOICE', '— Must I finish the work now? — No, you ______.', 'mustn''t', 'needn''t', 'can''t', 'shouldn''t', 'B', 'must 引导的疑问句，否定回答用 needn''t，表示“不必”。', '情态动词', 1),
(32, 11, 'CHOICE', 'He ______ be at home, for the light in his room is on.', 'can', 'must', 'need', 'may', 'B', '表示有把握的肯定推测，用 must。', '情态动词', 1),
(33, 11, 'CHOICE', 'You ______ have told her the news; she already knew it.', 'needn''t', 'mustn''t', 'can''t', 'shouldn''t', 'A', 'needn''t have done 表示“本不必做某事却做了”。', '情态动词', 1),
(34, 12, 'CHOICE', 'If I ______ you, I would accept the offer.', 'am', 'was', 'were', 'be', 'C', '与现在事实相反的虚拟条件句，be 动词一律用 were。', '虚拟语气', 1),
(35, 12, 'CHOICE', 'I wish I ______ to the party last night.', 'went', 'had gone', 'go', 'would go', 'B', 'wish 后的从句表示与过去事实相反，用过去完成时。', '虚拟语气', 1),
(36, 12, 'CHOICE', 'He suggested that we ______ the meeting until next week.', 'put off', 'putting off', 'to put off', 'puts off', 'A', 'suggest 表示“建议”时，从句谓语用 (should) + 动词原形。', '虚拟语气', 1),
(37, 13, 'CHOICE', '______ it not been for your help, I couldn''t have succeeded.', 'If', 'Had', 'Were', 'Should', 'B', '省略 if 的虚拟条件句需倒装，原句为 If it had not been for your help。', '复习虚拟语气', 1),
(38, 13, 'CHOICE', 'It is necessary that every student ______ the school rule.', 'obeys', 'obey', 'obeyed', 'is obeying', 'B', 'It is necessary that 后的主语从句用 (should) + 动词原形。', '复习虚拟语气', 1),
(39, 13, 'CHOICE', 'I would rather you ______ tomorrow instead of today.', 'come', 'came', 'will come', 'would come', 'B', 'would rather 后接从句时，用一般过去时表示对现在或将来的虚拟。', '复习虚拟语气', 1),
(40, 14, 'CHOICE', 'Neither of the two answers ______ correct.', 'are', 'is', 'were', 'be', 'B', 'neither of + 复数名词作主语，谓语动词用单数。', '阶段总复习', 1),
(41, 14, 'CHOICE', 'The book ______ cover is red belongs to me.', 'that', 'which', 'whose', 'who', 'C', '表示所属关系（书的封面）用关系代词 whose。', '阶段总复习', 1),
(42, 14, 'CHOICE', 'It was not until midnight ______ he came back home.', 'that', 'when', 'which', 'then', 'A', '这是强调句型 It was not until... that...，只能用 that。', '阶段总复习', 1),
(43, 15, 'CHOICE', 'Let''s go shopping this afternoon, ______?', 'shall we', 'will you', 'do we', 'don''t we', 'A', 'Let''s 开头的祈使句，反义疑问部分用 shall we。', '反义疑问句', 1),
(44, 15, 'CHOICE', 'He hardly ever goes to the cinema, ______?', 'does he', 'doesn''t he', 'is he', 'did he', 'A', 'hardly 表示否定含义，反义疑问部分用肯定形式。', '反义疑问句', 1),
(45, 15, 'CHOICE', 'I don''t think he is right, ______?', 'do I', 'is he', 'isn''t he', 'don''t I', 'B', '主语为第一人称的 I think/believe 结构，反义疑问部分与从句保持一致。', '反义疑问句', 1),
(46, 16, 'CHOICE', '______ beautiful the flowers are!', 'What', 'What a', 'How', 'How a', 'C', 'how 修饰形容词或副词，构成 How + adj./adv. + 主谓！', '感叹句', 1),
(47, 16, 'CHOICE', '______ interesting book it is!', 'What a', 'What an', 'How', 'How an', 'B', 'what 修饰名词，interesting 以元音音素开头，用 What an。', '感叹句', 1),
(48, 16, 'CHOICE', '______ fast the boy runs!', 'What', 'What a', 'How', 'How a', 'C', 'how 修饰副词 fast，构成感叹句。', '感叹句', 1),
(49, 17, 'CHOICE', 'It was in the park ______ I met my old friend.', 'where', 'that', 'which', 'when', 'B', '强调句型 It is/was + 被强调部分 + that...，被强调部分是地点状语也用 that。', '强调句', 1),
(50, 17, 'CHOICE', 'It was he ______ broke the window yesterday.', 'who', 'whom', 'which', 'whose', 'A', '强调主语且指人，用 who（也可用 that）。', '强调句', 1),
(51, 17, 'CHOICE', 'It ______ Tom that helped me with my English last week.', 'is', 'was', 'were', 'has been', 'B', '强调过去发生的事情，用 It was...that...。', '强调句', 1),
(52, 18, 'CHOICE', 'Hurry up, ______ you will be late for school.', 'and', 'or', 'but', 'so', 'B', '祈使句 + or + 陈述句，表示“否则就会……”。', '并列句和祈使句', 1),
(53, 18, 'CHOICE', 'Work hard, ______ you will succeed in the end.', 'and', 'or', 'but', 'for', 'A', '祈使句 + and + 陈述句，表示“那么就会……”。', '并列句和祈使句', 1),
(54, 18, 'CHOICE', '______ the door, please. It''s cold outside.', 'Close', 'Closing', 'To close', 'Closed', 'A', '祈使句以动词原形开头。', '并列句和祈使句', 1),
(55, 19, 'CHOICE', 'Only in this way ______ improve your spoken English.', 'you can', 'can you', 'you will', 'will can you', 'B', 'only + 状语置于句首时，主句用部分倒装。', '倒装句', 1),
(56, 19, 'CHOICE', 'Never ______ such a beautiful scene before.', 'I have seen', 'have I seen', 'I saw', 'did I saw', 'B', '否定副词置于句首时，句子用部分倒装，且用现在完成时。', '倒装句', 1),
(57, 19, 'CHOICE', 'Not only ______ interested in music, but also he likes sports.', 'he is', 'is he', 'he was', 'was he', 'B', 'not only 置于句首时，其后的分句用部分倒装。', '倒装句', 1),
(58, 20, 'CHOICE', 'It is the third time that he ______ late this week.', 'is', 'was', 'has been', 'had been', 'C', 'It is the ... time that 从句用现在完成时。', '复习五大句型', 1),
(59, 20, 'CHOICE', 'This is the room ______ he lived in last year.', 'which', 'where', 'that', 'what', 'C', '从句中介词 in 已出现，缺少宾语，用 that（which 亦可，但先行词被限定且选项设置如此）。', '复习五大句型', 1),
(60, 20, 'CHOICE', 'Neither he nor I ______ able to answer the question.', 'am', 'is', 'are', 'be', 'A', 'neither...nor 遵循就近原则，靠近谓语的 I 用 am。', '复习五大句型', 1),
(61, 21, 'CHOICE', 'The reason ______ he was late is that he missed the bus.', 'why', 'which', 'what', 'when', 'A', '先行词为 reason，且在从句中作原因状语，用 why。', '五大句型自测', 1),
(62, 21, 'CHOICE', '______ hard he tried, he still failed the exam.', 'However', 'Whatever', 'No matter', 'Although', 'A', 'however + 形容词/副词，相当于 no matter how。', '五大句型自测', 1),
(63, 21, 'CHOICE', 'It is high time that we ______ our environment.', 'protect', 'protected', 'will protect', 'protecting', 'B', 'It is high time that 从句用一般过去时表示虚拟。', '五大句型自测', 1),
(64, 22, 'CHOICE', '______ he said at the meeting surprised everyone.', 'That', 'What', 'Which', 'It', 'B', '从句中缺少宾语，用 what 引导主语从句，表示“……的事情”。', '主语从句', 1),
(65, 22, 'CHOICE', '______ is known to all, the earth moves around the sun.', 'As', 'It', 'That', 'What', 'A', 'as 引导非限制性定语从句，指代后面整个主句的内容。', '主语从句', 1),
(66, 22, 'CHOICE', '______ we will go camping tomorrow depends on the weather.', 'If', 'Whether', 'That', 'What', 'B', '主语从句表示“是否”时，只能用 whether，不能用 if。', '主语从句', 1),
(67, 23, 'CHOICE', 'He asked me ______ I had finished my homework.', 'that', 'if', 'what', 'which', 'B', '一般疑问句变为宾语从句，用 if/whether 引导。', '宾语从句', 1),
(68, 23, 'CHOICE', 'I don''t know ______ he will come or not.', 'if', 'whether', 'that', 'what', 'B', '与 or not 直接连用时，只能用 whether。', '宾语从句', 1),
(69, 23, 'CHOICE', 'Could you tell me ______?', 'where is the station', 'where the station is', 'where was the station', 'the station where is', 'B', '宾语从句必须用陈述语序。', '宾语从句', 1),
(70, 24, 'CHOICE', 'The reason why he failed is ______ he didn''t work hard.', 'because', 'that', 'why', 'for', 'B', '主语为 the reason 时，表语从句用 that 引导，不用 because。', '表语从句', 1),
(71, 24, 'CHOICE', 'It looks ______ it is going to rain.', 'as', 'as if', 'that', 'like', 'B', 'as if 引导表语从句，表示“看起来好像”。', '表语从句', 1),
(72, 24, 'CHOICE', 'The question is ______ we can finish the task on time.', 'that', 'whether', 'if', 'what', 'B', '表语从句中表示“是否”只能用 whether。', '表语从句', 1),
(73, 25, 'CHOICE', 'The news ______ our team won the match made us excited.', 'which', 'that', 'what', 'when', 'B', '从句说明 news 的具体内容且不缺成分，为同位语从句，用 that 引导。', '同位语从句', 1),
(74, 25, 'CHOICE', 'The fact ______ he was seriously ill made us worried.', 'which', 'that', 'what', 'why', 'B', '同位语从句解释 fact 的内容，用 that 引导且 that 不作成分。', '同位语从句', 1),
(75, 25, 'CHOICE', 'I have no idea ______ the meeting will begin.', 'that', 'when', 'which', 'what', 'B', 'idea 后接同位语从句，表示“会议何时开始”，用连接副词 when。', '同位语从句', 1),
(76, 26, 'CHOICE', 'This is the boy ______ father is a doctor.', 'who', 'whose', 'which', 'whom', 'B', '表示所属关系（男孩的父亲），用关系代词 whose。', '定语从句', 1),
(77, 26, 'CHOICE', 'I''ll never forget the day ______ we first met.', 'which', 'when', 'that', 'what', 'B', '先行词是时间 the day，在从句中作时间状语，用关系副词 when。', '定语从句', 1),
(78, 26, 'CHOICE', 'That is the very book ______ I want to buy.', 'which', 'who', 'that', 'what', 'C', '先行词被 the very 修饰时，只能用关系代词 that。', '定语从句', 1),
(79, 27, 'CHOICE', '______ he is young, he knows a lot about computers.', 'Although', 'Because', 'So', 'But', 'A', '两句之间为让步关系，用 although 引导让步状语从句。', '状语从句', 1),
(80, 27, 'CHOICE', 'He didn''t go to bed ______ he finished his homework.', 'until', 'when', 'while', 'as', 'A', 'not...until 表示“直到……才……”。', '状语从句', 1),
(81, 27, 'CHOICE', 'I will call you ______ I arrive in Beijing.', 'as soon as', 'as long as', 'so that', 'even if', 'A', 'as soon as 表示“一……就……”，引导时间状语从句。', '状语从句', 1),
(82, 28, 'CHOICE', '______ he will attend the meeting is still unknown.', 'If', 'Whether', 'That', 'What', 'B', '主语从句表示“是否”，用 whether 引导。', '复习六大从句', 1),
(83, 28, 'CHOICE', 'This is the house ______ we lived in last year.', 'where', 'which', 'what', 'whose', 'B', '从句中介词 in 后缺少宾语，用关系代词 which（或 that）。', '复习六大从句', 1),
(84, 28, 'CHOICE', 'He asked me ______ I could help him with his English.', 'that', 'if', 'what', 'which', 'B', '宾语从句表示“是否”，用 if（或 whether）引导。', '复习六大从句', 1);
